import{_ as a,o as s,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"Git diff 三种对比：工作区、暂存区与 HEAD","description":"弄清 HEAD、暂存区、工作区三层关系，以及 git diff、git diff --cached、git diff HEAD 各自比较什么。","frontmatter":{"title":"Git diff 三种对比：工作区、暂存区与 HEAD","date":"2026-06-13T00:00:00.000Z","tags":["Git","版本控制","开发环境"],"categories":["开发环境"],"description":"弄清 HEAD、暂存区、工作区三层关系，以及 git diff、git diff --cached、git diff HEAD 各自比较什么。"},"headers":[],"relativePath":"posts/开发环境/Git/Git diff 三种对比：工作区、暂存区与 HEAD.md","filePath":"posts/开发环境/Git/Git diff 三种对比：工作区、暂存区与 HEAD.md","lastUpdated":1790163617000}'),d={name:"posts/开发环境/Git/Git diff 三种对比：工作区、暂存区与 HEAD.md"};function n(p,t,o,c,l,r){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h2 id="工作区相对-head-的「未暂存变更」" tabindex="-1">工作区相对 HEAD 的「未暂存变更」 <a class="header-anchor" href="#工作区相对-head-的「未暂存变更」" aria-label="Permalink to &quot;工作区相对 HEAD 的「未暂存变更」&quot;">​</a></h2><p>Git 里文件大致有三个地方：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HEAD（最近一次提交）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>暂存区（git add 之后）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>工作区（你磁盘上正在改的文件）</span></span></code></pre></div><p>不带参数的 <code>git diff</code> 比较的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作区里的内容  vs  暂存区里的内容</span></span></code></pre></div><p>如果文件还没 <code>git add</code>，那暂存区还是上次提交的样子，所以效果上就是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你改动了、但还没 git add 的那些差异</span></span></code></pre></div><p>也就是注释里说的「<strong>未暂存变更</strong>」。</p><hr><h2 id="三种-diff-命令对比" tabindex="-1">三种 diff 命令对比 <a class="header-anchor" href="#三种-diff-命令对比" aria-label="Permalink to &quot;三种 diff 命令对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>看什么</th></tr></thead><tbody><tr><td><code>git diff</code></td><td>工作区 vs 暂存区（未 add 的改动）</td></tr><tr><td><code>git diff --cached</code></td><td>暂存区 vs HEAD（已 add、未 commit 的改动）</td></tr><tr><td><code>git diff HEAD</code></td><td>工作区 vs HEAD（所有未提交的改动）</td></tr></tbody></table><p>不带参数时用的是第一种，所以<strong>看不到</strong>已经 <code>git add</code> 进暂存区的内容。</p><hr><h2 id="一句话记忆" tabindex="-1">一句话记忆 <a class="header-anchor" href="#一句话记忆" aria-label="Permalink to &quot;一句话记忆&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git diff          → 还没 add 的</span></span>
<span class="line"><span>git diff --cached → 已经 add、还没 commit 的</span></span>
<span class="line"><span>git diff HEAD     → 上面两种加在一起（所有未提交）</span></span></code></pre></div>`,15)])])}const g=a(d,[["render",n]]);export{f as __pageData,g as default};
